// Space Collector game
// Canvas with id="game"
(() => {
  const canvas = document.getElementById('game');
  if (!canvas) return;
  const ctx = canvas.getContext('2d');
  const width = canvas.width = canvas.clientWidth || 800;
  const height = canvas.height = canvas.clientHeight || 600;

  // Player ship
  const ship = {
    x: width / 2,
    y: height - 40,
    w: 30,
    h: 30,
    speed: 5,
    dx: 0,
    dy: 0,
    draw() {
      ctx.fillStyle = '#0ff';
      ctx.fillRect(this.x - this.w / 2, this.y - this.h / 2, this.w, this.h);
    },
    update() {
      this.x = Math.max(this.w / 2, Math.min(width - this.w / 2, this.x + this.dx));
      this.y = Math.max(this.h / 2, Math.min(height - this.h / 2, this.y + this.dy));
    }
  };

  // Input handling
  const keys = {};
  window.addEventListener('keydown', e => { keys[e.key] = true; });
  window.addEventListener('keyup', e => { keys[e.key] = false; });

  const ores = [];
  const asteroids = [];
  let score = 0;
  let gameOver = false;

  function spawnOre() {
    ores.push({
      x: Math.random() * width,
      y: -20,
      r: 10,
      speed: 2 + Math.random() * 2
    });
  }
  function spawnAsteroid() {
    const size = 20 + Math.random() * 30;
    asteroids.push({
      x: Math.random() * width,
      y: -size,
      r: size / 2,
      speed: 1 + Math.random() * 2
    });
  }

  function updateEntities() {
    ores.forEach(o => { o.y += o.speed; });
    asteroids.forEach(a => { a.y += a.speed; });
    // Remove off‑screen
    while (ores.length && ores[0].y - ores[0].r > height) ores.shift();
    while (asteroids.length && asteroids[0].y - asteroids[0].r > height) asteroids.shift();
  }

  function checkCollisions() {
    // ship vs ore
    ores.forEach((o, i) => {
      const dx = o.x - ship.x;
      const dy = o.y - ship.y;
      const dist = Math.hypot(dx, dy);
      if (dist < o.r + Math.max(ship.w, ship.h) / 2) {
        score++;
        ores.splice(i, 1);
      }
    });
    // ship vs asteroid
    asteroids.forEach(a => {
      const dx = a.x - ship.x;
      const dy = a.y - ship.y;
      const dist = Math.hypot(dx, dy);
      if (dist < a.r + Math.max(ship.w, ship.h) / 2) { gameOver = true; }
    });
  }

  function draw() {
    ctx.clearRect(0, 0, width, height);
    // draw ship
    ship.draw();
    // draw ores
    ctx.fillStyle = '#ff0';
    ores.forEach(o => {
      ctx.beginPath();
      ctx.arc(o.x, o.y, o.r, 0, Math.PI * 2);
      ctx.fill();
    });
    // draw asteroids
    ctx.fillStyle = '#f44';
    asteroids.forEach(a => {
      ctx.beginPath();
      ctx.arc(a.x, a.y, a.r, 0, Math.PI * 2);
      ctx.fill();
    });
    // score
    ctx.fillStyle = '#fff';
    ctx.font = '20px sans-serif';
    ctx.fillText(`Score: ${score}`, 10, 30);
    if (gameOver) {
      ctx.fillStyle = 'rgba(0,0,0,0.5)';
      ctx.fillRect(0, 0, width, height);
      ctx.fillStyle = '#f00';
      ctx.textAlign = 'center';
      ctx.font = '48px sans-serif';
      ctx.fillText('Game Over', width / 2, height / 2);
    }
  }

  let oreTimer = 0, asteroidTimer = 0;
  function loop(timestamp) {
    if (gameOver) { draw(); return; }
    // input
    ship.dx = 0; ship.dy = 0;
    if (keys['ArrowLeft'] || keys['a']) ship.dx = -ship.speed;
    if (keys['ArrowRight'] || keys['d']) ship.dx = ship.speed;
    if (keys['ArrowUp'] || keys['w']) ship.dy = -ship.speed;
    if (keys['ArrowDown'] || keys['s']) ship.dy = ship.speed;
    ship.update();
    // spawn
    if (oreTimer > 80) { spawnOre(); oreTimer = 0; }
    if (asteroidTimer > 200) { spawnAsteroid(); asteroidTimer = 0; }
    oreTimer++; asteroidTimer++;
    // update & collisions
    updateEntities();
    checkCollisions();
    draw();
    requestAnimationFrame(loop);
  }
  requestAnimationFrame(loop);
})();
